import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_gelu_pool_kernel(const float* input, float* output, 
                                     int batch_size, int channels, 
                                     int input_h, int input_w) {
    const int batch = blockIdx.x;
    const int channel = blockIdx.y;

    float sum = 0.0f;
    const int num_elements = input_h * input_w;

    for(int idx = threadIdx.x; idx < num_elements; idx += blockDim.x) {
        const int h = idx / input_w;
        const int w = idx % input_w;
        const int input_idx = batch * channels * num_elements + 
                             channel * num_elements + 
                             h * input_w + w;

        float val = input[input_idx];
        // GELU approximation
        float gelu = val * 0.5f * (1.0f + erff(val * 0.7071067811865475f));
        sum += gelu;
    }

    __shared__ float shared_sum[256];
    shared_sum[threadIdx.x] = sum;
    __syncthreads();

    // Parallel reduction
    for(int offset = blockDim.x/2; offset > 0; offset >>= 1) {
        if(threadIdx.x < offset) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + offset];
        }
        __syncthreads();
    }

    if(threadIdx.x == 0) {
        output[batch * channels + channel] = shared_sum[0] / num_elements;
    }
}

torch::Tensor fused_gelu_pool_cuda(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto input_h = input.size(2);
    auto input_w = input.size(3);

    auto output = torch::zeros({batch_size, channels}, input.options());

    dim3 grid(batch_size, channels);
    const int threads = 256;

    fused_gelu_pool_kernel<<<grid, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        input_h,
        input_w
    );

    return output;
}
"""

fused_ops_cpp = "torch::Tensor fused_gelu_pool_cuda(torch::Tensor input);"

fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=fused_ops_cpp,
    cuda_sources=fused_ops_source,
    functions=['fused_gelu_pool_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, padding=kernel_size//2)
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv(x)
        x = self.fused_ops.fused_gelu_pool_cuda(x.contiguous())
        return x
